# Check that the current environment (e.g. envs/baseline = origin/main) can load fixtures
# generated by another one (e.g. envs/new). Writes `<BT_OUT or out>/load_check/<mode>/<name>.toml`.
# Usage: julia --project=envs/<mode> lib/check_load.jl <mode> <fixture_name> [more names...]
include(joinpath(@__DIR__, "common.jl"))
const MODE_ = ARGS[1]
const DIR = joinpath(abspath(get(ENV, "BT_OUT", joinpath(BT_ROOT, "out"))), "load_check", MODE_)
mkpath(DIR)
status = 0
for name in ARGS[2:end]
    rec = Dict{String, Any}("name" => name, "mode" => MODE_, "fixture_data" => FIX_DATA)
    try
        t = @elapsed lf = load_fixture(name)
        rec["status"] = "ok"
        rec["seconds"] = t
        rec["res_type"] = string(typeof(lf.res))
        rec["extras"] = string.(collect(keys(lf.fx)))
    catch err
        global status = 1
        io = IOBuffer(); showerror(io, err); s = String(take!(io))
        rec["status"] = "error"
        rec["error"] = first(s, 2000)
    end
    println(rpad(rec["status"], 8), name, " ", get(rec, "error", "")[1:min(end, 300)])
    open(io -> TOML.print(io, rec), joinpath(DIR, name * ".toml"), "w")
end
exit(status)
